<template>
 <section class="research-experiment-result" aria-label="研究实验结果">
  <el-alert v-if="experiment.error" :title="experiment.error" type="error" :closable="false"/>
  <p v-if="detail.project?.template_id" class="research-method-note">内置双均线方法实验；不代表原研报全部模型或历史收益的复刻。</p><div v-if="['queued','preparing','running'].includes(experiment.status)" class="research-result-progress"><span>{{experiment.status==='queued'?'实验等待研究进程执行':'WT 原生回测运行中'}}</span><el-progress :percentage="Math.min(100,Math.max(0,Number(experiment.progress)||0))"/></div>
  <template v-if="!compact">
   <div class="research-metrics"><div v-for="item in metrics" :key="item.key"><span>{{item.label}}</span><strong>{{number(detail.metrics?.[item.key],item.unit)}}</strong></div></div>
   <div class="research-fund-heading"><h3>原生日结净盈亏</h3><small>原生累计值 · 已扣费用、包含浮盈 · 元</small></div><div v-if="fundPoints.length" ref="fundChart" class="research-fund-chart" role="img" aria-label="WT 原生日结累计净盈亏曲线"/><p v-else class="research-result-empty">还没有原生日结资金记录。</p>
  </template>
  <div class="research-diagnostics"><h3>策略诊断</h3><p>{{detail.diagnostics?.message||'该实验尚无诊断记录。'}}</p><div v-if="diagnosticCounts.length" class="research-diagnostic-counts"><span v-for="item in diagnosticCounts" :key="item.key">{{item.label}}<b>{{detail.diagnostics[item.key]}}</b></span></div><details v-if="detail.diagnostics?.samples?.length"><summary>查看均线与目标仓位样本</summary><el-table :data="detail.diagnostics.samples" max-height="320" class="research-sample-table"><el-table-column prop="time" label="时间" min-width="160"/><el-table-column label="快均线" min-width="100"><template #default="{row}">{{number(row.fast)}}</template></el-table-column><el-table-column label="慢均线" min-width="100"><template #default="{row}">{{number(row.slow)}}</template></el-table-column><el-table-column prop="target" label="目标手数" min-width="90"/></el-table></details></div>
  <template v-if="!compact"><h3>原生成交</h3><el-table :data="detail.trades||[]" max-height="350" empty-text="这次实验没有成交。请结合诊断查看预热、信号及目标变化。"><el-table-column prop="code" label="合约" min-width="150"/><el-table-column prop="time" label="时间" min-width="155"/><el-table-column label="方向" width="80"><template #default="{row}">{{direction(row.direction)}}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}">{{offset(row.offset)}}</template></el-table-column><el-table-column prop="price" label="价格" width="95"/><el-table-column prop="volume" label="手数" width="70"/><el-table-column label="费用" width="85"><template #default="{row}">{{number(row.fee)}}</template></el-table-column><el-table-column prop="tag" label="标记" min-width="120"/></el-table><details v-if="experiment.log_tail||detail.log_tail" class="research-log"><summary>运行日志尾部</summary><pre>{{experiment.log_tail||detail.log_tail}}</pre></details></template>
 </section>
</template>
<script>
import {markRaw} from 'vue'
import * as echarts from 'echarts'
import {themeState} from '@/js/theme.js'
export default {
 name:'ResearchExperimentResult',props:{detail:{type:Object,required:true},compact:Boolean},
 data:()=>({chart:null,metrics:[{key:'trade_count',label:'成交记录',unit:''},{key:'closed_trades',label:'平仓回合',unit:''},{key:'signal_count',label:'信号记录',unit:''},{key:'fee',label:'原生手续费',unit:' 元'},{key:'total_return',label:'区间收益率',unit:'%'},{key:'max_drawdown',label:'最大回撤',unit:'%'},{key:'sharpe',label:'夏普比率',unit:''},{key:'days',label:'回测日数',unit:''}]}),
 computed:{experiment(){return this.detail.experiment||{}},theme(){return themeState.value},fundPoints(){return (this.detail.funds||[]).filter(row=>Number.isFinite(Number(row.dynbalance))&&row.dynbalance!==null&&row.dynbalance!==undefined).map(row=>[String(row.date),Number(row.dynbalance)])},diagnosticCounts(){return [{key:'calculations',label:'计算回调'},{key:'warmup_skips',label:'预热跳过'},{key:'long_signals',label:'多头判定'},{key:'short_signals',label:'空头判定'},{key:'target_changes',label:'目标变化'}].filter(item=>this.detail.diagnostics?.[item.key]!==null&&this.detail.diagnostics?.[item.key]!==undefined)}},
 watch:{detail:{deep:true,handler(){this.$nextTick(this.draw)}},theme(){this.$nextTick(this.draw)}},
 mounted(){this.$nextTick(this.draw);this._resize=()=>this.chart?.resize();window.addEventListener('resize',this._resize)},beforeUnmount(){window.removeEventListener('resize',this._resize);this.chart?.dispose()},
 methods:{number(value,unit=''){if(value===null||value===undefined||value===''||!Number.isFinite(Number(value)))return'—';return Number(value).toLocaleString('zh-CN',{maximumFractionDigits:3})+unit},direction(value){return {LONG:'多',SHORT:'空',long:'多',short:'空',BUY:'买',SELL:'卖'}[value]||value||'—'},offset(value){return {OPEN:'开仓',CLOSE:'平仓',CLOSETODAY:'平今',CLOSEYESTERDAY:'平昨',open:'开仓',close:'平仓'}[value]||value||'—'},draw(){if(!this.$refs.fundChart||this.compact)return;if(!this.chart)this.chart=markRaw(echarts.init(this.$refs.fundChart));const css=getComputedStyle(document.documentElement),text=css.getPropertyValue('--wt-text').trim(),muted=css.getPropertyValue('--wt-muted').trim(),line=css.getPropertyValue('--wt-line').trim(),surface=css.getPropertyValue('--wt-surface').trim();this.chart.setOption({animation:false,grid:{left:72,right:22,top:20,bottom:40},tooltip:{trigger:'axis',backgroundColor:surface,textStyle:{color:text},borderColor:line},xAxis:{type:'category',data:this.fundPoints.map(row=>row[0]),axisLabel:{color:muted,hideOverlap:true},axisLine:{lineStyle:{color:line}}},yAxis:{type:'value',scale:true,axisLabel:{color:muted},splitLine:{lineStyle:{color:line}}},series:[{name:'累计净盈亏（元）',type:'line',data:this.fundPoints.map(row=>row[1]),showSymbol:this.fundPoints.length<30,lineStyle:{color:text,width:2},itemStyle:{color:text}}]},true);this.chart.resize()}}
}
</script>
<style scoped>
.research-method-note{font-size:12px;line-height:1.8;color:var(--wt-muted);padding:12px 14px;background:var(--wt-matte);border-left:2px solid var(--wt-line)}.research-experiment-result{font-size:12px;color:var(--wt-text);margin-top:20px}.research-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--wt-line);border-radius:6px;overflow:hidden;margin:20px 0}.research-metrics>div{display:flex;flex-direction:column;gap:8px;padding:16px;border-bottom:1px solid var(--wt-line)}.research-metrics span{font-size:11px;color:var(--wt-muted)}.research-metrics strong{font-size:18px;font-weight:550;overflow-wrap:anywhere}.research-metrics>div:nth-last-child(-n+4){border-bottom:0}.research-fund-heading{display:flex;align-items:center;justify-content:space-between;gap:15px}.research-fund-heading h3{margin:15px 0}.research-fund-heading small{color:var(--wt-muted)}h3{font-weight:550;font-size:15px;margin:28px 0 14px}.research-fund-chart{width:100%;height:280px}.research-result-empty{padding:35px 10px;color:var(--wt-muted);text-align:center}.research-diagnostics{padding-top:4px}.research-diagnostics>p{font-size:12px;line-height:1.8;color:var(--wt-muted);white-space:pre-wrap}.research-diagnostic-counts{display:flex;flex-wrap:wrap;gap:10px 22px;padding:15px 0}.research-diagnostic-counts span{display:flex;align-items:center;gap:10px;color:var(--wt-muted)}.research-diagnostic-counts b{color:var(--wt-text);font-weight:550}.research-diagnostics details,.research-log{margin:18px 0}.research-diagnostics summary,.research-log summary{cursor:pointer;color:var(--wt-text);font-size:12px}.research-sample-table{margin-top:15px}.research-result-progress{padding:18px 0}.research-result-progress>span{display:block;margin-bottom:12px}.research-log pre{background:var(--wt-matte);padding:15px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto;font:12px/1.8 Consolas,monospace}.research-experiment-result :deep(.el-table){font-size:12px}
@media(max-width:650px){.research-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.research-metrics>div{padding:13px}.research-metrics>div:nth-last-child(-n+4){border-bottom:1px solid var(--wt-line)}.research-metrics>div:nth-last-child(-n+2){border-bottom:0}.research-metrics strong{font-size:17px}.research-fund-heading{align-items:flex-start;flex-direction:column;gap:0}.research-fund-chart{height:230px}}
</style>
